import { existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { defineConfig } from 'vite'

const __dirname = dirname(fileURLToPath(import.meta.url))

/**
 * Generated by `scripts/build-wasm.mjs` (wasm-bindgen --target web). The main
 * thread transcoder statically imports this glue, so it must exist at build
 * time. The sibling `_bg.wasm` is copied into `dist/` by vite.config.worker.ts
 * (not here); the module fetches it at runtime by URL.
 */
const GLUE_SRC = resolve(__dirname, 'wasm', 'pkg', 'acad_rust_converter.js')
const MAIN_THREAD_OUT_NAME = 'acad-rust-converter-main-thread.js'

if (!existsSync(GLUE_SRC)) {
  throw new Error(
    `[acad-rust-converter] Missing WASM glue:\n  ${GLUE_SRC}\n` +
      'Run `pnpm build:wasm` first (requires the Rust toolchain: cargo + ' +
      'wasm32-unknown-unknown + wasm-bindgen-cli 0.2.126).'
  )
}

/**
 * Main-thread transcoder: `src/main-thread.ts` + the inlined wasm-bindgen glue,
 * emitted as an ESM module (`acad-rust-converter-main-thread.js`) that the
 * converter dynamically imports only when `useWorker: false`. This keeps the
 * parser glue out of the main library chunk (same isolation rationale as the
 * worker build), while serving hosts that cannot use a Web Worker.
 */
export default defineConfig({
  build: {
    outDir: 'dist',
    // The main config owns `emptyOutDir`; this runs last and only adds files.
    emptyOutDir: false,
    lib: {
      entry: resolve(__dirname, 'src', 'main-thread.ts'),
      formats: ['es'],
      fileName: () => MAIN_THREAD_OUT_NAME
    },
    minify: true
  }
})
